from typing import List, Set

def generate(length: int, initial: int = 1) -> List[int]:
    if length < 0 or initial <= 0:
        raise ValueError("invalid input")
    if length == 0:
        return []
    values: List[int] = [initial]
    sums: Set[int] = {2 * initial}
    while len(values) < length:
        z = values[-1] + 1
        while z in sums:
            z += 1
        old = tuple(values)
        values.append(z)
        sums.update(x + z for x in old)
        sums.add(2 * z)
    return values

if __name__ == "__main__":
    print(generate(20))

from typing import Sequence, Tuple

def certify(values: Sequence[int]) -> Tuple[bool, str]:
    if not values or values[0] != 1:
        return False, "the prefix must begin at 1"
    for n in range(len(values) - 1):
        sums = {x + y for x in values[:n+1] for y in values[:n+1]}
        z = values[n+1]
        if z <= values[n]:
            return False, f"non-increasing step at index {n+1}"
        if z in sums:
            return False, f"term {z} is a prior pair sum"
        if any(w not in sums for w in range(values[n] + 1, z)):
            return False, f"term {z} is admissible but not minimal"
    return True, "valid greedy prefix"

if __name__ == "__main__":
    print(certify([1, 3, 5, 7, 9]))
    print(certify([1, 1, 2, 4, 7]))

from typing import List, Sequence, Tuple

def additive_triples(values: Sequence[int]) -> List[Tuple[int, int, int]]:
    return [(i, j, k) for k in range(len(values)) for i in range(k)
            for j in range(k) if values[i] + values[j] == values[k]]

if __name__ == "__main__":
    print("greedy:", additive_triples([1, 3, 5, 7, 9]))
    print("triangular:", additive_triples([1, 1, 2, 4, 7]))

